import math

M = 26


def encode(plain_text, a, b):
    if math.gcd(a, M) != 1:
        raise ValueError("a and m must be coprime.")

    result = []
    for char in plain_text:
        if char.isalpha():
            x = ord(char.lower()) - ord("a")
            result.append(chr((a * x + b) % M + ord("a")))
        elif char.isdigit():
            result.append(char)

    return " ".join(
        "".join(result)[i : i + 5] for i in range(0, len(result), 5)
    )


def decode(ciphered_text, a, b):
    if math.gcd(a, M) != 1:
        raise ValueError("a and m must be coprime.")

    mmi = next(x for x in range(M) if (a * x) % M == 1)

    result = []
    for char in ciphered_text:
        if char.isalpha():
            y = ord(char.lower()) - ord("a")
            result.append(chr((mmi * (y - b)) % M + ord("a")))
        elif char.isdigit():
            result.append(char)

    return "".join(result)
